public class CoinInventory
{
    private readonly Dictionary<decimal, int> _coins = new()
    {
        { 1.00m, 10 }, { 0.50m, 20 }, { 0.25m, 50 },
        { 0.10m, 100 }, { 0.05m, 100 }
    };

    public bool TryMakeChange(decimal amount, out Dictionary<decimal, int> change)
    {
        change = new();
        var denominations = _coins.Keys.OrderByDescending(d => d).ToList();
        decimal remaining = amount;

        foreach (var denom in denominations)
        {
            if (remaining <= 0) break;
            int needed = (int)(remaining / denom);
            int available = _coins[denom];
            int use = Math.Min(needed, available);
            if (use > 0)
            {
                change[denom] = use;
                _coins[denom] -= use;
                remaining -= use * denom;
            }
        }
        return remaining == 0;
    }
}
